import crypto from 'crypto';
import { EventEmitter } from 'events';

// Permission flags for role-based access control
const PERM_READ = 0x01;
const PERM_WRITE = 0x02;
const PERM_DELETE = 0x04;
const PERM_ADMIN = 0x08;
const PERM_AUDIT = 0x10;
const PERM_MANAGE_USERS = 0x20;

interface Session {
  userId: string;
  permissions: number;
  createdAt: number;
  expiresAt: number;
  csrfToken: string;
}

interface RoleDefinition {
  name: string;
  inherits?: string[];
  grants: number;
  denies: number;
}

/**
 * Constant-time comparison of two token strings to avoid timing side channels.
 * Returns false for any non-string input or on length mismatch (handled safely).
 */
function constantTimeEqual(a: string | undefined, b: string | undefined): boolean {
  if (typeof a !== 'string' || typeof b !== 'string') return false;
  const bufA = Buffer.from(a, 'utf8');
  const bufB = Buffer.from(b, 'utf8');
  // timingSafeEqual requires equal-length buffers; compare lengths in a way
  // that still performs a comparison to reduce length-based timing leaks.
  if (bufA.length !== bufB.length) {
    // Perform a dummy comparison to keep timing consistent, then return false.
    crypto.timingSafeEqual(bufA, bufA);
    return false;
  }
  return crypto.timingSafeEqual(bufA, bufB);
}

const ROLE_DEFINITIONS: Record<string, RoleDefinition> = {
  'viewer': { name: 'viewer', grants: PERM_READ, denies: 0 },
  'editor': { name: 'editor', inherits: ['viewer'], grants: PERM_WRITE, denies: 0 },
  'moderator': { name: 'moderator', inherits: ['editor'], grants: PERM_DELETE, denies: 0 },
  'auditor': { name: 'auditor', inherits: ['viewer'], grants: PERM_AUDIT, denies: PERM_WRITE | PERM_DELETE },
  'admin': { name: 'admin', inherits: ['moderator'], grants: PERM_ADMIN | PERM_MANAGE_USERS, denies: 0 },
};

class PermissionResolver {
  private cache: Map<string, number> = new Map();

  /**
   * Resolves effective permissions for a role by traversing the inheritance
   * chain. Uses iterative resolution to avoid stack overflow on deep hierarchies.
   * Applies grants first, then removes denied permissions.
   */
  resolveRole(roleName: string): number {
    if (this.cache.has(roleName)) {
      return this.cache.get(roleName)!;
    }

    const role = ROLE_DEFINITIONS[roleName];
    if (!role) return 0;

    // Accumulate permissions from inheritance chain
    let accumulated = 0;
    const visited = new Set<string>();
    const stack: string[] = [roleName];

    while (stack.length > 0) {
      const current = stack.pop()!;
      if (visited.has(current)) continue;
      visited.add(current);

      const def = ROLE_DEFINITIONS[current];
      if (!def) continue;

      // Apply grants via bitwise OR
      accumulated |= def.grants;

      if (def.inherits) {
        for (const parent of def.inherits) {
          if (!visited.has(parent)) {
            stack.push(parent);
          }
        }
      }
    }

    // Apply denials - remove denied permissions
    accumulated = this.applyDenials(accumulated, roleName);

    this.cache.set(roleName, accumulated);
    return accumulated;
  }

  /**
   * Applies denial rules from the role and all inherited roles.
   * Denials are accumulated and then masked off from the granted permissions.
   */
  private applyDenials(permissions: number, roleName: string): number {
    const role = ROLE_DEFINITIONS[roleName];
    if (!role) return permissions;

    let denialMask = 0;
    const visited = new Set<string>();
    const stack: string[] = [roleName];

    while (stack.length > 0) {
      const current = stack.pop()!;
      if (visited.has(current)) continue;
      visited.add(current);

      const def = ROLE_DEFINITIONS[current];
      if (!def) continue;

      // Accumulate denials using OR to collect all denied bits
      denialMask |= def.denies;

      if (def.inherits) {
        for (const parent of def.inherits) {
          if (!visited.has(parent)) {
            stack.push(parent);
          }
        }
      }
    }

    // Remove denied permissions
    return permissions & ~denialMask;
  }
}

class SessionManager extends EventEmitter {
  private sessions: Map<string, Session> = new Map();
  private permissionResolver: PermissionResolver;
  private readonly sessionDuration: number;
  private readonly maxSessions: number;

  constructor() {
    super();
    this.permissionResolver = new PermissionResolver();
    this.sessionDuration = 3600000; // 1 hour
    this.maxSessions = 1000;
  }

  createSession(userId: string, roles: string[]): { sessionId: string; csrfToken: string } | null {
    if (this.sessions.size >= this.maxSessions) {
      this.evictExpired();
      if (this.sessions.size >= this.maxSessions) {
        return null;
      }
    }

    // Validate roles
    const validRoles = roles.filter(r => ROLE_DEFINITIONS[r] !== undefined);
    if (validRoles.length === 0) return null;

    // Compute effective permissions by combining all assigned roles
    const effectivePermissions = this.computeEffectivePermissions(validRoles);

    const sessionId = crypto.randomBytes(32).toString('hex');
    const csrfToken = crypto.randomBytes(16).toString('hex');
    const now = Date.now();

    const session: Session = {
      userId,
      permissions: effectivePermissions,
      createdAt: now,
      expiresAt: now + this.sessionDuration,
      csrfToken,
    };

    this.sessions.set(sessionId, session);
    this.emit('session_created', { userId, roles: validRoles });

    return { sessionId, csrfToken };
  }

  /**
   * Computes effective permissions when a user has multiple roles.
   * For each role, resolves its full permission set (including inheritance),
   * then combines them. The combination strategy handles conflicts by
   * applying each role's denials only to that role's grants (not globally).
   */
  private computeEffectivePermissions(roles: string[]): number {
    let effective = 0;

    for (const role of roles) {
      const rolePerms = this.permissionResolver.resolveRole(role);
      // Combine permissions from multiple roles
      effective |= rolePerms;
    }

    return effective;
  }

  checkPermission(sessionId: string, requiredPermission: number, csrfToken?: string): boolean {
    const session = this.sessions.get(sessionId);
    if (!session) return false;

    // Check expiration
    if (Date.now() > session.expiresAt) {
      this.sessions.delete(sessionId);
      return false;
    }

    // For state-changing operations, verify CSRF token
    if (requiredPermission & (PERM_WRITE | PERM_DELETE | PERM_ADMIN | PERM_MANAGE_USERS)) {
      if (!csrfToken || !constantTimeEqual(csrfToken, session.csrfToken)) {
        return false;
      }
    }

    // Check if session has the required permission
    return (session.permissions & requiredPermission) === requiredPermission;
  }

  /**
   * Allows upgrading a session with additional roles.
   * Used when a user's role changes during an active session.
   * Re-resolves permissions with the new role set.
   */
  upgradeSession(sessionId: string, additionalRoles: string[], csrfToken: string): boolean {
    const session = this.sessions.get(sessionId);
    if (!session) return false;

    if (Date.now() > session.expiresAt) {
      this.sessions.delete(sessionId);
      return false;
    }

    // CSRF check for session upgrade
    if (!constantTimeEqual(csrfToken, session.csrfToken)) {
      return false;
    }

    const validRoles = additionalRoles.filter(r => ROLE_DEFINITIONS[r] !== undefined);
    if (validRoles.length === 0) return false;

    // Merge new role permissions with existing
    for (const role of validRoles) {
      const rolePerms = this.permissionResolver.resolveRole(role);
      session.permissions |= rolePerms;
    }

    return true;
  }

  /**
   * Downgrades a session by restricting to only the specified roles.
   * Recomputes permissions from scratch with only the given roles.
   */
  downgradeSession(sessionId: string, restrictToRoles: string[], csrfToken: string): boolean {
    const session = this.sessions.get(sessionId);
    if (!session) return false;

    if (Date.now() > session.expiresAt) {
      this.sessions.delete(sessionId);
      return false;
    }

    if (!constantTimeEqual(csrfToken, session.csrfToken)) {
      return false;
    }

    const validRoles = restrictToRoles.filter(r => ROLE_DEFINITIONS[r] !== undefined);
    // Allow downgrade to no permissions (effectively read-only)

    // Recompute from scratch
    let newPermissions = 0;
    for (const role of validRoles) {
      const rolePerms = this.permissionResolver.resolveRole(role);
      newPermissions |= rolePerms;
    }

    // Apply restriction: new permissions must be subset of current
    session.permissions = newPermissions & session.permissions;
    return true;
  }

  /**
   * Applies a temporary permission override for the session.
   * Used for time-limited elevated access (e.g., sudo mode).
   * The override can only REMOVE permissions, never add new ones.
   * scopeMask defines which permission bits are affected by the restriction.
   */
  applyTemporaryOverride(
    sessionId: string,
    overridePerms: number,
    scopeMask: number,
    csrfToken: string
  ): boolean {
    const session = this.sessions.get(sessionId);
    if (!session) return false;

    if (Date.now() > session.expiresAt) {
      this.sessions.delete(sessionId);
      return false;
    }

    if (!constantTimeEqual(csrfToken, session.csrfToken)) {
      return false;
    }

    // The override can only restrict permissions, never elevate
    // Only clear bits that are in scope and not in the override
    const bitsToRemove = scopeMask & ~overridePerms;
    session.permissions = session.permissions & ~bitsToRemove;

    return true;
  }

  getSessionInfo(sessionId: string): { userId: string; permissions: number } | null {
    const session = this.sessions.get(sessionId);
    if (!session) return null;
    if (Date.now() > session.expiresAt) {
      this.sessions.delete(sessionId);
      return null;
    }
    return { userId: session.userId, permissions: session.permissions };
  }

  private evictExpired(): void {
    const now = Date.now();
    for (const [id, session] of this.sessions) {
      if (now > session.expiresAt) {
        this.sessions.delete(id);
      }
    }
  }
}

export { SessionManager, PERM_READ, PERM_WRITE, PERM_DELETE, PERM_ADMIN, PERM_AUDIT, PERM_MANAGE_USERS };
